{
  "filecontent": null,
  "displayorder": 13,
  "pagetemplateid": "718ed8c8-9407-4620-adf3-832ec188887d",
  "parentpageid": "551cf2a7-4cb2-4424-8af7-3422ddbd968e",
  "partialurl": "Forgot-Password",
  "isroot": false,
  "rootwebpageid": "07dd9f0b-2605-5700-3dbe-d421d635aab4",
  "title": "Forgot Password",
  "summary": "<p>This is a sample landing page designed to be a starting point for your website</p>",
  "copy": "{% include 'cmdspp_ToastModal' %}
<div class="cmdspp-forgot-wrapper cmdspp-registration-pages-bg">
  <div class="cmdspp-forgot-left">
    <div class="cmdspp-secure-badge"><span>•</span>OFFICIAL GOVERNMENT PORTAL · SECURE CONNECTION</div>
    <h1>Connecting Healthcare Professionals Across the Nation</h1>
    <p class="cmdspp-description">The National Medical Enrollment Portal is the single authoritative registry for licensed physicians, specialists, and allied health professionals operating within the healthcare system.</p>
    <div class="cmdspp-benefits">
      <div><img src="/cmdspp_greenTickCircle"/>  HIPAA Compliant Infrastructure</div>
      <div><img src="/cmdspp_greenTickCircle"/>  256-bit TLS Encryption</div>
      <div><img src="/cmdspp_greenTickCircle"/>  ISO 27001:2022 Certified</div>
    </div>
  </div>
  <div class="cmdspp-forgot-card">
    <h2>Forgot Password</h2>
    <p>Authorised personnel only. All sessions are monitored.</p>
    <label>Email Address</label><input type="email" id="emailAddress" maxlength="100" placeholder="Enter email address" /><button id="verificationPinBtn" type="button">Get Verification PIN</button>
  </div>
</div>
<div class="row sectionBlockLayout text-start" style="display: none; flex-wrap: wrap; margin: 0px; min-height: auto; padding: 8px;">
  <div class="container" style="padding: 0px; display: flex; flex-wrap: wrap;"><div class="col-lg-12 columnBlockLayout" style="flex-grow: 1; display: flex; flex-direction: column; min-width: 250px;"></div></div>
</div>",
  "publishingstateid": "c7294317-419f-4724-8068-a91d5da8d92c",
  "enablerating": false,
  "enabletracking": false,
  "excludefromsearch": false,
  "hiddenfromsitemap": true,
  "sharedpageconfiguration": false,
  "feedbackpolicy": 756150000,
  "customcss": ".cmdspp-forgot-wrapper{
    display: flex;
    min-height: calc(100vh - 124px);
    align-items: center;
    justify-content: space-between;
    padding: clamp(40px, 11vh, 105px) clamp(24px, 5.5vw, 80px);
}

/* LEFT SECTION */

.cmdspp-forgot-left{
    width:50%;
    max-width:615px;
}

.cmdspp-secure-badge{
    width: 380px;
    display:inline-block;
    background:#0B3A6F1A;
    border:1px solid #0B3A6F26;
    padding:7px 17px;
    border-radius:20px;
    color:#0B3A6FE5;
    margin-bottom:30px;
    font-weight: 400;
    font-size: 12px;
    line-height: 16px;
    letter-spacing: 0.3px;
    text-transform: uppercase;
    span{
        color: #00D492 !important;
    }
}

.cmdspp-forgot-left h1{
    color: #0B3A6F;
    font-size: 54px;
    font-weight: 400 !important;
    line-height: 62px;
    margin-bottom: 33px;
}

.cmdspp-description{
    max-width: 520px;
    color: #0B3A6F;
    font-weight: 400 !important;
    font-size: 16px;
    line-height: 26px;
    letter-spacing: 0px;
    margin-bottom: 61px;
}

.cmdspp-benefits div{
    margin-bottom: 10px;
    color: #0B3A6F;
    font-size: 14px;
    line-height: 20px;
    font-weight: 400 !important;
}

/* CARD */

.cmdspp-forgot-card{
    position: relative;
    width:450px;
    background: #ffffff;
    border-radius: 14px;
    padding: 32px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.08);
    overflow: hidden;
    /* border-top: 4px solid #1d428a; */
}

.cmdspp-forgot-card::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;

    width: 100%;
    height: 4px;

    background: linear-gradient(
        90deg,
        #1A3A6B 0%,
        #00A6F4 50%,
        #1A3A6B 100%
    );
}

.cmdspp-forgot-card h2{
    font-weight: 400 !important;
    font-size: 22.4px;
    line-height: 33.6px;
    letter-spacing: 0px;
    text-align: center;
    text-transform: capitalize;
    margin: 0 0 5.7px;
    color: #0F1F3D;
}

.cmdspp-forgot-card p{
    font-weight: 400 !important;
    font-size: 12px;
    line-height: 16px;
    letter-spacing: 0px;
    text-align: center;
    color: #5A7099;
    margin-bottom: 32px;  
}

.cmdspp-forgot-card label{
    color: #0B3A6F;
    display:block;
    font-weight: 400 !important;
    font-size: 12px;
    line-height: 16px;
    letter-spacing: 0px;
    margin-bottom:4px;
}

.cmdspp-forgot-card input{
    width:100%;
    height:36px;
    padding:8px;
    border:1px solid #E3E8EE;
    border-radius:4px;
    margin-bottom:16px;
    box-shadow: 0px 1px 2px rgba(55, 65, 81, 0.08);
    font-weight: 400 !important;
    font-size: 14px;
    line-height: 24px;
    color: #0B3A6F;
    outline: none !important;
}

.cmdspp-forgot-card input::placeholder{
    text-decoration: none !important;
    font-size: 14px;
    font-weight: 400 !important;
    line-height: 20px;
    color: #0B3A6F; 
    opacity: 0.4;
}

.cmdspp-forgot-card input:focus{
    box-shadow: 0px 0px 0px 1px #6C8EEF inset, 0px 0px 0px 2px #D6ECFF;
}

.cmdspp-forgot-card button{
    width:100%;
    height:40px;
    background:#274463;
    box-shadow: 0px 1px 2px -1px #0000001A;
    border:none;
    color:white;
    border-radius:8px;
    cursor:pointer;
    margin-top: 18px;
    font-weight: 400 !important;
    font-size: 14px;
    line-height: 20px;
    letter-spacing: 0px;
    text-align: center;
}

.cmdspp-forgot-card button:hover{

    background:#1c3964;
}

.cmdspp-field-error {
    box-shadow: inset 0 0 0 1px #CD3D64, 0 0 0 2px #FDE2DD !important;
}

/* RESPONSIVE */

@media(max-width:1100px){

    .cmdspp-forgot-wrapper{

        flex-direction:column;
        gap:40px;
    }

    .cmdspp-forgot-left{

        width:100%;
        max-width:none;
    }

    .cmdspp-forgot-card{

        width:100%;
        max-width:520px;
    }

    .cmdspp-forgot-left h1{

        font-size:48px;
    }
}",
  "customjavascript": "$("#verificationPinBtn").on("click", async function () {

    const email = $("#emailAddress").val()?.trim();

    // Required validation
    if (!email) {

        cmdsppShowToast(
            "error",
            "Email address is required"
        );
        $("#emailAddress").addClass("cmdspp-field-error");

        return;
    }

    try {
        const $button = $(this);
        $button.prop("disabled", true);

        const flowUrl =  window.flowConfig.cmdspp_validateUserExists;
        const response = await fetch(flowUrl, {

            method: "POST",

            headers: {
                "Content-Type": "application/json"
            },

            body: JSON.stringify({
                transType:"validateuserEmail",
                email: email
            })

        });

        // let pay = {
        //     text:JSON.stringify({
        //         "transType":"validateuserEmail",
        //         "email": email
        //    })
        //    }
        // const response = await cmdsppExecutePowerPageFlow("/_api/cloudflow/v1.0/trigger/670ccffb-cd90-f111-8076-70a8a5b02d34",pay)
        $button.prop("disabled", false);

        const result = await response.json();

        if (result.exists) {

            console.log("Record Id:", result.recordId);
            sessionStorage.setItem("forgotPassword","true");

            // Navigate to verification page
            window.location.href = "/validate-pin?id="+result.recordId;

        } else {

            cmdsppShowToast(
                "error",
                "Invalid credentials"
            );

        }

    } catch (error) {

        console.error(error);

        cmdsppShowToast(
            "error",
            "An unexpected error occurred. Please try again."
        );

    }

});

$(document).on(
    "input",
    "#emailAddress",
    function () {
        $(this).removeClass("cmdspp-field-error");
    }
);"
}
